WITH unpivoted AS (SELECT id, category, metric_name, metric_value FROM (SELECT id, category, price, cost FROM products) src UNPIVOT INCLUDE NULLS (metric_value FOR metric_name IN (price, cost))) SELECT CASE WHEN metric_value >= 86 THEN 'LARGE' ELSE 'SMALL' END AS metric_value_tier, AVG(metric_value) FILTER (WHERE metric_name = 'price') AS price_avg_metric_value, ROUND(SUM(metric_value) / NULLIF(COUNT(CASE WHEN metric_name = 'cost' THEN 1 END), 0), 2) AS metric_value_per_cost, COUNT(*) AS cnt, COUNT_IF(category = 'Electronics') AS electronics_events FROM unpivoted GROUP BY 1 ORDER BY metric_value_tier ASC NULLS LAST
